//! Handler of `GET /workouts/program`.

use axum::{extract::State, Json};

use crate::{auth::AuthUser, errors::AppResult, models::program::ProgramResponse, AppState};

/// `GET /workouts/program`
///
/// Returns the training program of the authenticated user (see `openapi.yaml`).
/// It is generated by the ML engine, or served from the cache if the engine fails.
///
/// # Responses
/// - `200 OK` — a [`ProgramResponse`] (`source` is `generated` or `cache`).
/// - `401 Unauthorized` — missing or invalid Bearer token (rejected by [`AuthUser`]).
/// - `503 Service Unavailable` — the ML engine failed and no program is cached.
///
/// # Errors
/// Returns the [`crate::errors::AppError`] of the service, rendered as a JSON error.
pub async fn get_program(
    State(state): State<AppState>,
    // The extractor runs before the handler body: no valid token, no call.
    AuthUser(user_id): AuthUser,
) -> AppResult<Json<ProgramResponse>> {
    let program = state.program_service.get_program(user_id).await?;
    Ok(Json(program))
}
